@sig trait InventoryAcquisition_Api {
  def id: Art.BridgeId
  def inventory_snapshot_Id : Art.PortId
  def material_boundary_facts_Id : Art.PortId
  def product_boundary_facts_Id : Art.PortId

  // Logika spec var representing port state for outgoing data port
  @spec var material_boundary_facts: Factory_Dispatch_Coordinator.MaterialBoundaryFacts = $

  def put_material_boundary_facts(value : Factory_Dispatch_Coordinator.MaterialBoundaryFacts) : Unit = {
    Contract(
      Modifies(material_boundary_facts),
      Ensures(
        material_boundary_facts == value
      )
    )
    Spec {
      material_boundary_facts = value
    }

    Art.putValue(material_boundary_facts_Id, Factory_Dispatch_Coordinator.MaterialBoundaryFacts_Payload(value))
  }

  // Logika spec var representing port state for outgoing data port
  @spec var product_boundary_facts: Factory_Dispatch_Coordinator.ProductBoundaryFacts = $

  def put_product_boundary_facts(value : Factory_Dispatch_Coordinator.ProductBoundaryFacts) : Unit = {
    Contract(
      Modifies(product_boundary_facts),
      Ensures(
        product_boundary_facts == value
      )
    )
    Spec {
      product_boundary_facts = value
    }

    Art.putValue(product_boundary_facts_Id, Factory_Dispatch_Coordinator.ProductBoundaryFacts_Payload(value))
  }

  def logInfo(msg: String): Unit = {
    Art.logInfo(id, msg)
  }

  def logDebug(msg: String): Unit = {
    Art.logDebug(id, msg)
  }

  def logError(msg: String): Unit = {
    Art.logError(id, msg)
  }
}

@datatype class InventoryAcquisition_Initialization_Api (
  val id: Art.BridgeId,
  val inventory_snapshot_Id : Art.PortId,
  val material_boundary_facts_Id : Art.PortId,
  val product_boundary_facts_Id : Art.PortId) extends InventoryAcquisition_Api

@datatype class InventoryAcquisition_Operational_Api (
  val id: Art.BridgeId,
  val inventory_snapshot_Id : Art.PortId,
  val material_boundary_facts_Id : Art.PortId,
  val product_boundary_facts_Id : Art.PortId) extends InventoryAcquisition_Api {

  // Logika spec var representing port state for incoming data port
  @spec var inventory_snapshot: Factory_Dispatch_Coordinator.InventorySnapshot = $

  def get_inventory_snapshot() : Option[Factory_Dispatch_Coordinator.InventorySnapshot] = {
    Contract(
      Ensures(
        Res == Some(inventory_snapshot)
      )
    )
    val value : Option[Factory_Dispatch_Coordinator.InventorySnapshot] = Art.getValue(inventory_snapshot_Id) match {
      case Some(Factory_Dispatch_Coordinator.InventorySnapshot_Payload(v)) => Some(v)
      case Some(v) =>
        Art.logError(id, s"Unexpected payload on port inventory_snapshot.  Expecting 'Factory_Dispatch_Coordinator.InventorySnapshot_Payload' but received ${v}")
        None[Factory_Dispatch_Coordinator.InventorySnapshot]()
      case _ => None[Factory_Dispatch_Coordinator.InventorySnapshot]()
    }
    return value
  }
}
